# November 22, 2026: a first scatter of places across the rest of Saskatchewan, away from the two earlier batches
# (Saskatoon and the South Branch; the southeast). The Battlefords and the 1885 sites of the North Saskatchewan
# (Fort Battleford, Fort Pitt, Frenchman Butte, Steele Narrows), the Cypress Hills (Fort Walsh and the massacre site),
# Wood Mountain, Gravelbourg, Moose Jaw, Regina, Last Mountain Lake, Humboldt, Prince Albert, Veregin, Fort Livingstone,
# Cumberland House and Stanley Mission. Region sk taken with tools/choose.py --claim --thinnest.
# Sources were opened in this session: the Canadian Register of Historic Places (historicplaces.ca) statement for most
# places, read with tools/page.py --all; Wikipedia as raw text (tools/wiki_raw.py); the Museums Association of
# Saskatchewan listings (Fort Walsh, Fort Battleford, Veregin); Parks Canada's Fort Battleford hours and fees pages and
# its Cypress Hills Massacre page; governmenthousesk.ca; the Legislative Assembly's tour and access pages;
# humboldtmuseum.ca; the Town of Gravelbourg's pages; Tourism Saskatchewan listings; HMdb (Steele Narrows marker).
from data_b import N
from data_ma import W
def L(t,u): return [t,u]
def HP(t,i): return ['Canadian Register of Historic Places: '+t,'https://www.historicplaces.ca/en/rep-reg/place-lieu.aspx?id=%d'%i]
BATCH={'key':'sk_qvtr','label':'Saskatchewan: the Battlefords to the Cypress Hills, Regina and the north','added':'2026-11-22 09:41'}
